+    return (this.quant_tables[args.q][0x00] == 0) or
+            (this.quant_tables[args.q][0x01] == 0) or
+            (this.quant_tables[args.q][0x02] == 0) or
+            (this.quant_tables[args.q][0x03] == 0) or
