+    var dst_bytes_per_pixel : base.u32[..= 32]
+    var dst_bytes_per_row   : base.u64
+    var src_bytes_per_pixel : base.u32[..= 8]
+    var tab                 : table base.u8
+    var dst                 : slice base.u8
+    var i                   : base.u64
+    var j                   : base.u64
+    var n                   : base.u64
