+    t0 = s0_707F._mm_xor_si128(b: x0)
+    t1 = t0._mm_clmulepi64_si128(b: k1k2, imm8: 0x00)
+    t2 = t0._mm_clmulepi64_si128(b: k1k2, imm8: 0x11)
+    aa = t1._mm_xor_si128(b: t2)._mm_xor_si128(b: s0_8F80)
+
+    // Main loop.
