+    tail_index = args.x.length() & 0xFFFF_FFFF_FFFF_FFF0  // And-not 16.
+    if tail_index < args.x.length() {
+        iterate (p = args.x[tail_index ..])(length: 1, advance: 1, unroll: 1) {
+            s = ECMA_TABLE[0][((s & 0xFF) as base.u8) ^ p[0]] ^ (s >> 8)
+        }
+    }
